package status

import (
	"slices"

	"k8s.io/apimachinery/pkg/apis/meta/v1/unstructured"
	"k8s.io/apimachinery/pkg/types"
	"sigs.k8s.io/controller-runtime/pkg/client"
)

// the map containing the references
type ObjectReferenceList struct {
	Items []ObjectReference `json:"items,omitempty"`
}

// DeepCopyInto is an autogenerated deepcopy function, copying the receiver, writing into out. in must be non-nil.
func (in *ObjectReferenceList) DeepCopyInto(out *ObjectReferenceList) {
	*out = *in
}

// DeepCopy is an autogenerated deepcopy function, copying the receiver, creating a new SimpleReplicatorStatus.
func (in *ObjectReferenceList) DeepCopy() *ObjectReferenceList {
	if in == nil {
		return nil
	}
	out := new(ObjectReferenceList)
	in.DeepCopyInto(out)
	return out
}

// the actual reference from the object in the cluster
type ObjectReference struct {
	ApiVersion string    `json:"apiversion"`
	Kind       string    `json:"kind"`
	Namespace  string    `json:"namespace"`
	Name       string    `json:"name"`
	UID        types.UID `json:"uid"`
}

// add object to list
func (orl *ObjectReferenceList) Append(o client.Object) {
	orl.Items = append(orl.Items, ObjectReferenceFromObject(o))
}

// remove object from list
func (orl *ObjectReferenceList) Remove(o client.Object) {
	orl.Items = slices.DeleteFunc(orl.Items, func(r ObjectReference) bool {
		return r.ApiVersion == o.GetObjectKind().GroupVersionKind().GroupVersion().String() &&
			r.Kind == o.GetObjectKind().GroupVersionKind().GroupKind().Kind &&
			r.Namespace == o.GetNamespace() &&
			r.Name == o.GetName() &&
			r.UID == o.GetUID()

	})
}

// get a reference from a given cliet.Object
func ObjectReferenceFromObject(o client.Object) ObjectReference {
	return ObjectReference{
		ApiVersion: o.GetObjectKind().GroupVersionKind().GroupVersion().String(),
		Kind:       o.GetObjectKind().GroupVersionKind().GroupKind().Kind,
		Namespace:  o.GetNamespace(),
		Name:       o.GetName(),
		UID:        o.GetUID(),
	}
}

// receive client.Object from the object reference
func (or ObjectReference) GetObject() client.Object {
	var o = &unstructured.Unstructured{}
	o.SetAPIVersion(or.ApiVersion)
	o.SetKind(or.Kind)
	o.SetNamespace(or.Namespace)
	o.SetName(or.Name)
	o.SetUID(or.UID)
	return o
}
